// src/lib/dermacureContent.ts
function ids(value) {
  try {
    const parsed = JSON.parse(value || "[]");
    return Array.isArray(parsed) ? parsed.filter((id) => typeof id === "string") : [];
  } catch {
    return [];
  }
}
function dermacureMenu(profile, services) {
  const headings = profile.sectionHeadings || {};
  const hidden = new Set(ids(headings.clinicHiddenServices));
  const order = ids(headings.clinicServiceOrder);
  return services.filter((s) => !hidden.has(s.id)).slice().sort((a, b) => {
    const ai = order.indexOf(a.id), bi = order.indexOf(b.id);
    return (ai < 0 ? order.length : ai) - (bi < 0 ? order.length : bi);
  });
}
function dermacureFeatured(profile, services) {
  const selection = ids(profile.sectionHeadings?.clinicFeaturedServices);
  const chosen = selection.map((id) => services.find((s) => s.id === id)).filter((s) => !!s);
  return [...chosen, ...services.filter((s) => !chosen.includes(s) && s.popular), ...services.filter((s) => !chosen.includes(s) && !s.popular)].slice(0, 3);
}
function clinicServiceGroup(profile, service) {
  let overrides = {};
  try {
    overrides = JSON.parse(profile.sectionHeadings?.clinicServiceGroups || "{}");
  } catch {
  }
  const group = overrides[service.id];
  if (group === "skin" || group === "hair" || group === "cosmetology") return group;
  const text = `${service.name} ${service.category}`.toLowerCase();
  if (/hair|scalp|alopecia|dandruff/.test(text)) return "hair";
  if (/dermatolog|consultation|acne|scar|pigment|melasma|eczema|dermatitis|psoriasis|warts|rosacea|skin concern|skin treatment/.test(text)) return "skin";
  return "cosmetology";
}
function clinicServiceIsApproved(service) {
  return service.clinicServiceApproved === true;
}
function clinicServiceIsPublished(service) {
  return clinicServiceIsApproved(service) && service.clinicPublicationStatus === "published";
}
function clinicPriceIsVerified(service) {
  return clinicServiceIsPublished(service) && service.clinicFeeStatus === "verified" && service.clinicPriceVerified === true && typeof service.price === "number" && Number.isFinite(service.price) && service.price >= 0;
}
function clinicPublicServices(profile, services) {
  const ids2 = new Set(services.map((s) => s.id));
  const enquiry = (Array.isArray(profile.clinicEnquiryServices) ? profile.clinicEnquiryServices : []).filter((s) => s && !ids2.has(s.id));
  const menu3 = dermacureMenu(profile, [...services, ...enquiry]);
  return profile.subdomain ? menu3.filter(clinicServiceIsPublished) : menu3;
}
function clinicPriceLabel(service, currency = "\u20B9") {
  if (clinicPriceIsVerified(service)) return `${currency}${service.price.toLocaleString("en-IN")}`;
  if (service.clinicDemoData === true && typeof service.price === "number" && Number.isFinite(service.price) && service.price >= 0) {
    return `Demo price \xB7 ${currency}${service.price.toLocaleString("en-IN")}`;
  }
  return "Contact clinic for pricing";
}
function clinicPublicEmail(value) {
  const email = typeof value === "string" ? value.trim() : "";
  return email.length <= 254 && /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,63}$/i.test(email) ? email : "";
}
function clinicPhone(value) {
  const text = typeof value === "string" ? value.trim() : "";
  if (!/^\+?[0-9\s().-]+$/.test(text)) return "";
  const digits = text.replace(/\D/g, "");
  return digits.length >= 10 && digits.length <= 15 ? (text.startsWith("+") ? "+" : "") + digits : "";
}

