// src/lib/socialVideoSource.ts
function socialVideoSource(raw) {
  try {
    const url = new URL(raw.trim());
    if (url.protocol !== "https:") return null;
    const host = url.hostname.toLowerCase().replace(/^www\./, "").replace(/^m\./, "");
    if (host === "instagram.com") {
      const match = url.pathname.match(/^\/(?:reel|reels|p|tv)\/([\w-]+)\/?$/);
      return match ? { platform: "Instagram", id: match[1], url: `https://www.instagram.com${url.pathname}` } : null;
    }
    if (!["youtube.com", "youtu.be", "youtube-nocookie.com"].includes(host)) return null;
    const id = host === "youtu.be" ? url.pathname.slice(1) : url.searchParams.get("v") || url.pathname.match(/^\/(?:shorts|embed|v)\/([\w-]+)/)?.[1];
    return id && /^[\w-]{11}$/.test(id) ? { platform: "YouTube", id, url: raw.trim() } : null;
  } catch {
    return null;
  }
}
function secureMediaUrl(raw) {
  try {
    const url = new URL(raw || "");
    return url.protocol === "https:" ? url.href : "";
  } catch {
    return "";
  }
}
function shortVideoSource(raw) {
  const source = socialVideoSource(raw);
  if (!source) return null;
  const path = new URL(raw.trim()).pathname;
  if (source.platform === "YouTube" && !/^\/shorts\/[\w-]{11}\/?$/.test(path)) return null;
  if (source.platform === "Instagram" && !/^\/reels?\/[\w-]+\/?$/.test(path)) return null;
  return { ...source, url: source.platform === "YouTube" ? `https://www.youtube.com/shorts/${source.id}` : source.url };
}
function reelSource(video) {
  return video.categoryTag === "LONG" ? null : shortVideoSource(video.youtubeUrl);
}

// src/lib/websiteContent.ts
var WEBSITE_SECTIONS = { header: true, hero: true, metrics: true, about: true, services: true, packages: true, stylists: true, testimonials: true, gallery: true, location: true, whatsappFloat: true, videos: true, promo: true, social: true, loyalty: true, policies: true, bookings: true, share: true };
function socialUrl(value, platform) {
  const raw = (value || "").trim();
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) {
    try {
      const url = new URL(raw);
      return ["http:", "https:"].includes(url.protocol) ? url.href : "";
    } catch {
      return "";
    }
  }
  if (raw.includes(":")) return "";
  if (/^(www\.)?(instagram|facebook|youtube|tiktok)\.com\//i.test(raw)) return `https://${raw}`;
  const handle = raw.replace(/^@/, "");
  return /^[\w.\-]+$/.test(handle) ? `https://${platform}.com/${platform === "youtube" || platform === "tiktok" ? "@" : ""}${handle}` : "";
}
function websiteSections(profile) {
  return { ...WEBSITE_SECTIONS, ...profile.websiteSections };
}

