var KEY = "nexora_customer_referral";
var valid = (code) => /^[A-Z0-9-]{6,32}$/.test(code);
function captureCustomerReferral() {
  const params = new URLSearchParams(location.search);
  const code = (params.get("customer_ref") || (params.has("app") ? params.get("ref") : "") || "").trim().toUpperCase();
  try {
    if (valid(code)) {
      localStorage.setItem(KEY, JSON.stringify({ code, expires: Date.now() + 30 * 864e5 }));
      return code;
    }
    const saved = JSON.parse(localStorage.getItem(KEY) || "null");
    if (saved && saved.expires > Date.now() && valid(saved.code)) return saved.code;
    localStorage.removeItem(KEY);
  } catch {
  }
  return valid(code) ? code : "";
}
function clearCustomerReferral() {
  try {
    localStorage.removeItem(KEY);
  } catch {
  }
  const url = new URL(location.href);
  url.searchParams.delete("customer_ref");
  if (url.searchParams.get("auth") === "signup") url.searchParams.delete("auth");
  if (url.searchParams.has("app")) url.searchParams.delete("ref");
  history.replaceState(null, "", url);
}
function rememberCustomerReferral(code) {
  clearCustomerReferral();
  const normalized = code.trim().toUpperCase();
  try {
    if (valid(normalized)) localStorage.setItem(KEY, JSON.stringify({ code: normalized, expires: Date.now() + 30 * 864e5 }));
  } catch {
  }
  window.dispatchEvent(new Event("nexora-referral-changed"));
}

