// src/lib/emailService.ts
async function sendBookingEmail(params) {
  if (!params.to || !params.to.includes("@")) {
    return {
      success: false,
      error: "Please provide a valid recipient email address."
    };
  }
  try {
    const response = await fetch("/api/send-booking-email", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(params),
      signal: AbortSignal.timeout(12e3)
    });
    if (response.ok) {
      const data = await response.json();
      return {
        success: true,
        delivered: data.delivered,
        simulated: data.simulated,
        emailId: data.emailId,
        subject: data.subject,
        notice: data.notice
      };
    }
  } catch (err) {
    console.warn("Server proxy email endpoint unreachable; attempting Supabase Edge Function...", err);
  }
  try {
    const { data, error } = await supabase.functions.invoke("studioflow-booking-emails", {
      body: params
    });
    if (error) {
      const msg = error.message || "Email delivery failed";
      return {
        success: false,
        error: msg
      };
    }
    return {
      success: true,
      delivered: data?.delivered,
      simulated: data?.simulated,
      emailId: data?.emailId,
      notice: data?.notice,
      subject: data?.subject
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Failed to send automated email";
    return {
      success: false,
      error: msg
    };
  }
}
async function sendBookingConfirmationEmail(params) {
  return sendBookingEmail({
    ...params,
    type: "confirmation"
  });
}
async function sendBookingReminderEmail(params) {
  return sendBookingEmail({
    ...params,
    type: "reminder"
  });
}

